contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0 && amount <= 10 ether, "amount must be positive and bounded");
        require(address(this).balance >= amount, "insufficient test contract balance");

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterDepositUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterWithdrawUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert((!reverted) == (afterWithdrawUser == 0));
    }

    receive() external payable {}
}

